package com.bitedash.service; import com.bitedash.dto.*; import com.bitedash.entity.*; import com.bitedash.exception.*; import com.bitedash.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class ReviewService {private final ReviewRepository reviews; private final UserRepository users; private final RestaurantRepository restaurants; public ReviewService(ReviewRepository r,UserRepository u,RestaurantRepository p){reviews=r;users=u;restaurants=p;} @Transactional public ReviewResponse add(Long uid,Long rid,ReviewRequest x){User u=users.findById(uid).orElseThrow(()->new NotFoundException("User not found"));Restaurant r=restaurants.findById(rid).filter(Restaurant::isActive).orElseThrow(()->new NotFoundException("Restaurant not found"));if(reviews.existsByUserIdAndRestaurantId(uid,rid))throw new BadRequestException("You have already reviewed this restaurant");return ReviewResponse.of(reviews.save(new Review(u,r,x.rating(),x.comment())));} @Transactional(readOnly=true) public List<ReviewResponse> list(Long rid){if(!restaurants.existsById(rid))throw new NotFoundException("Restaurant not found");return reviews.findByRestaurantIdOrderByCreatedAtDesc(rid).stream().map(ReviewResponse::of).toList();}}
